  const { name, ext } = path.parse(fileName);

  let slugified = slugify(name);
  if (slugified.length === 0 || slugified.length > 100) {
    slugified = alphaid(8);
  }

  let key = `${alphaid(12)}/${slugified}${ext}`;
  if (userId) {
    key = `${userId}/${key}`;
  }

  const url = this.buildSasUrl(key, BlobSASPermissions.parse('cw'));
  return { key, url };
}

