fn mgr(&mut self, action: ActionCow) -> Result<Data> {
	let cx = &mut Ctx::new(&action, &mut self.app.core, &mut self.app.term)?;

	macro_rules! on {
		($name:ident) => {
			if action.name == stringify!($name) {
				return act!(mgr:$name, cx, action)
			}
		};
	}

	}
}

